export interface Footer01Props {
  brand?: string;
  description?: string;
  copyright?: string;
  eyebrow?: string;
  title?: string;
  contactLabel?: string;
  contactHref?: string;
  edition?: string;
  legalLinks?: { label: string; href: string }[];
  groups?: { title: string; links: { label: string; href: string }[] }[];
}
export const defaultGroups = [
  {
    title: "Explore",
    links: [
      { label: "Shop", href: "/shop" },
      { label: "Our story", href: "/about" },
      { label: "Journal", href: "/journal" },
    ],
  },
  {
    title: "Support",
    links: [
      { label: "Contact", href: "/contact" },
      { label: "Shipping & returns", href: "/help" },
      { label: "Size guide", href: "/size-guide" },
    ],
  },
];

.footer01 {
  padding: var(--space-6) var(--container-padding-lg) var(--space-4);
  border-block-start: var(--border-width-thin) solid var(--border-default);
  color: var(--text-primary);
  background: var(--surface-base);
}
.footer01 *,
.footer01 *::before,
.footer01 *::after {
  box-sizing: border-box;
}
.footer01-inner {
  max-width: var(--container-max-width);
  margin-inline: auto;
}
.footer01 :is(h2, h3, p) {
  margin: 0;
}
.footer01 .footer01-masthead {
  gap: var(--space-4);
  padding-block-end: var(--space-5);
  border-bottom: var(--border-width-thin) solid var(--border-default);
  font-size: var(--typography-micro-size);
  font-weight: var(--font-weight-semibold);
  letter-spacing: var(--letter-spacing-widest);
}
.footer01-dot {
  width: var(--space-1);
  height: var(--space-1);
  background: var(--brand-primary);
  border-radius: var(--radius-full);
}
.footer01 .footer01-top {
  gap: var(--website-column-gap);
  padding-block: var(--website-section-padding);
}
.footer01 .footer01-intro {
  flex: 0 1 45%;
  gap: var(--space-5);
}
.footer01 .footer01-title {
  max-width: var(--website-copy-width);
  font-size: var(--website-title-size);
  line-height: var(--line-height-tight);
  letter-spacing: var(--letter-spacing-tighter);
  text-wrap: balance;
}
.footer01 .footer01-intro p {
  max-width: var(--website-copy-width);
  font-size: var(--website-copy-size);
  line-height: var(--line-height-relaxed);
}
.footer01-navigation {
  flex: 1 1 0;
  min-width: 0;
  padding-inline-start: var(--website-column-gap);
  border-inline-start: var(--border-width-thin) solid var(--border-default);
}
.footer01 .footer01-links {
  gap: var(--space-8);
  flex-wrap: wrap;
}
.footer01 .footer01-group {
  flex: 1 1 0;
  gap: var(--space-4);
  min-width: min(100%, calc(var(--space-4) * 7));
}
.footer01 .footer01-group-title {
  margin-block-end: var(--space-2);
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-widest);
  text-transform: uppercase;
}
.footer01 a {
  color: var(--text-secondary);
  text-decoration: none;
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-normal);
  overflow-wrap: anywhere;
}
.footer01 a:hover {
  color: var(--text-primary);
  text-decoration: underline;
}
.footer01 a:focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring-color);
  outline-offset: var(--focus-ring-offset);
}
.footer01 .footer01-contact {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-8);
  padding-block: var(--space-3);
  border-bottom: var(--border-width-thin) solid var(--border-strong);
  color: var(--text-primary);
  font-weight: var(--font-weight-semibold);
  margin-block-start: var(--space-3);
}
.footer01 .footer01-signature {
  gap: var(--space-4);
  padding-block: var(--space-6);
  border-block: var(--border-width-thin) solid var(--border-default);
}
.footer01-wordmark {
  min-width: 0;
  font-family: var(--font-family-display);
  font-size: var(--website-wordmark-size);
  font-weight: var(--font-weight-bold);
  line-height: var(--line-height-none);
  letter-spacing: var(--letter-spacing-tighter);
  overflow-wrap: anywhere;
}
.footer01-signature-arrow {
  flex-shrink: 0;
  font-size: var(--font-size-4xl);
  color: var(--brand-primary);
}
.footer01 .footer01-bottom {
  padding-block-start: var(--space-4);
  gap: var(--space-4);
}
.footer01 .footer01-bottom p,
.footer01 .footer01-legal a {
  font-size: var(--typography-micro-size);
}
@media (max-width: 760px) {
  .footer01 {
    padding-inline: var(--container-padding);
  }
  .footer01 .footer01-top {
    flex-direction: column;
    gap: var(--space-8);
    padding-block: var(--space-8);
  }
  .footer01 .footer01-intro {
    flex-basis: auto;
  }
  .footer01-navigation {
    width: 100%;
    padding-inline-start: 0;
    padding-block-start: var(--space-6);
    border-inline-start: 0;
    border-block-start: var(--border-width-thin) solid var(--border-default);
  }
  .footer01 .footer01-links {
    gap: var(--space-6);
  }
}
